head.script:
///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS02030.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.selIndex = "";
scwin.dataTp = "";
scwin.rdoVal = "";
                dma_search.set("txnId", $c.data.getParameter("txnId"));
                // data Point 값을 넣는다                
                dlt_dataPoint.setJSON($c.data.getParameter("dataPoint"));

                // 참조 DATA POINT Enumulation값만 있는 데이 조회
                const enumList = dlt_dataPoint.getAllJSON();
                enumList.forEach(function(cont) {
                    if (!$c.util.isEmpty(cont.enumList)) {
                        sbx_dataPoint.addItem(cont.dataId, cont.dataNm);
                    }
                });
                scwin.fnSearch();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.rdo_axies_onclick = function (index, value) {

                // 초기화
                sbx_dataPoint.setValue("");                
                dlt_enum.removeAll();
                dlt_com.removeAll();
                ibx_axis1.setValue("");
                ibx_axis2.setValue("");
                ibx_axis3.setValue("");
                ibx_member.setValue("");

                if (!$c.util.isEmpty(scwin.selIndex)) {
                    dlt_list.setCellData(scwin.selIndex, "isButton", "선택");
                    scwin.selIndex = "";
                }                
                scwin.fnButtonVisible(value);
            };

            scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {

                if (columnId === "isButton") {
                    // 웹스퀘어는 트리형태로 사용 할 경우 보이는 rowIndex 기준으로 하기 때문에 close된 항목이 
                    // 있을 경우 rowIndex가 틀어져 버리는 문제가 있어 getRealRowIndex를 필수로 사용
                    const realIndex = grd_list.getRealRowIndex(rowIndex);
                    // 그리드 값 변경                    
                    dlt_list.setCellData(realIndex, "isButton", "선택됨");
                    if (!$c.util.isEmpty(scwin.selIndex) && realIndex !== scwin.selIndex) {
                        dlt_list.setCellData(scwin.selIndex, "isButton", "선택");
                    }
                    scwin.selIndex = realIndex;

                    if (scwin.rdoVal === "0") {
                        // 상위 명을 가져오는 처리
                        for (let i=scwin.selIndex; i > 0; i--) {
                            if (dlt_list.getCellData(scwin.selIndex, "upElmtId") === dlt_list.getCellData(i, "elmtId")) {
                                ibx_axis1.setValue(dlt_list.getCellData(i, "elmtKorLabl"));
                                // 선택된 축의 DataType
                                scwin.dataTp = dlt_list.getCellData(i, "dataTp");
                                break;
                            }
                        }                    
                        ibx_member.setValue(dlt_list.getCellData(scwin.selIndex, "elmtKorLabl"));
                    } else if (scwin.rdoVal === "1") {
                        ibx_axis2.setValue(dlt_list.getCellData(scwin.selIndex, "elmtKorLabl"));

                        // 초기화
                        dlt_com.removeAll();
                        // 하위에 Member찾아서 처리
                        const lvl_ = dlt_list.getCellData(scwin.selIndex, "elmtLvl");
                        let index_ = 0;
                        for (let i=(scwin.selIndex + 1); i < dlt_list.getRowCount(); i++) {
                            if (lvl_ >= parseInt(dlt_list.getCellData(i, "elmtLvl"))) {
                                break;
                            } else {
                                if (dlt_list.getCellData(i, "elmtTp") === "MEMB" && dlt_list.getCellData(i, "isLeaf") === "1") {
                                    dlt_com.insertRow(index_);
                                    dlt_com.setCellData(index_, "elmtKorLabl", dlt_list.getCellData(i, "elmtKorLabl"));
                                    dlt_com.setCellData(index_, "elmtId", dlt_list.getCellData(i, "elmtId"));
                                    index_++;
                                }
                            }
                        }
                        sbx_dataPoint.setDisabled(false);

                        // Enumueration 초기화
                        for (let i=0; i < dlt_enum.getRowCount(); i++) {
                            dlt_enum.setCellData(i, "member", "");
                        }
                    } else {
                        ibx_axis3.setValue(dlt_list.getCellData(scwin.selIndex, "elmtKorLabl"));
                    }
                    // 그리드 button 스타일 변경
                    scwin.fnButtonProc();
                }
            };

            scwin.grd_list_onscrolly = function (e) {

                // 기존에 체크되서 변경되어 정보 있는지 체크
                if (!$c.util.isEmpty(scwin.selIndex)) {
                    scwin.fnButtonProc();
                }
            };

            scwin.grd_list_ontoggleclick = function (collapsed, rowIndex) {

                // 기존에 체크되서 변경되어 정보 있는지 체크
                if (!$c.util.isEmpty(scwin.selIndex) && !collapsed) {
                    scwin.fnButtonProc();
                }
            };

            scwin.sbx_dataPoint_onchange = function (info) {

                // 초기화
                dlt_enum.removeAll();
                // DataList 해당 정보를 조회해서 Enumeration정보 여부 체크
                for (let i=0; i < dlt_dataPoint.getRowCount(); i++) {
                    if (dlt_dataPoint.getCellData(i, "dataId") === info.newValue) {                        
                        if (!$c.util.isEmpty(dlt_dataPoint.getCellData(i, "enumList"))) {
                            const items = (dlt_dataPoint.getCellData(i, "enumList")).split("|");                                                        
                            for (let j=0; j < items.length; j++) {                                   
                                const index = dlt_enum.insertRow();

                                const cont = items[j];
                                dlt_enum.setCellData(index, "enumVal", cont.substring(0, cont.indexOf(":")));
                                dlt_enum.setCellData(index, "enumKorLabl", cont.substring(cont.indexOf(":")+1, cont.indexOf("(")));
                                dlt_enum.setCellData(index, "enumEnLabl", cont.substring(cont.indexOf("(")+1, cont.indexOf(")")));
                            }
                        }
                        grp_content2_2.show();
                        grp_content2_3.show();
                        tbx_content2.show();
                        break;
                    }
                }
            };

            scwin.chk_kind_onviewchange = function (info) {

                if (info.checked) {
                    grp_content1_3.show();
                } else {
                    grp_content1_3.hide();
                    sbx_standard.setValue("");
                }
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

            scwin.btn_select_onclick = function (e) {

                const params = {};
                if ($c.util.isEmpty(scwin.selIndex)) {
                    $c.win.alert("축/멤버를 추가 해주세요.");
                    return;
                }

                let list = [];                
                if (scwin.rdoVal === "0") {
                    params.axisId = dlt_list.getCellData(scwin.selIndex, "upElmtId");
                    params.axisLabl = ibx_axis1.getValue();
                    params.axisTypCd = scwin.dataTp;
                    params.membId = dlt_list.getCellData(scwin.selIndex, "elmtId");
                    params.membLabl = dlt_list.getCellData(scwin.selIndex, "elmtKorLabl");
                    params.refDpId = "";

                    if (chk_kind.getValue() === "Y") {
                        params.condBasDpId = sbx_standard.getValue();
                    } else {
                        params.condBasDpId = "";
                    }
                    params.enumList = null;                    
                } else if (scwin.rdoVal === "1") {
                    // 참조 DATAPOINT 체크
                    if ($c.util.isEmpty(sbx_dataPoint.getValue())) {
                        $c.win.alert("참조 DATAPOINT를 선택 해주세요", function () { sbx_dataPoint.focus(); });
                        return;
                    }
                    params.axisId = dlt_list.getCellData(scwin.selIndex, "elmtId");
                    params.axisLabl = dlt_list.getCellData(scwin.selIndex, "elmtKorLabl");
                    params.axisTypCd = dlt_list.getCellData(scwin.selIndex, "dataTp");
                    params.membId = "";
                    params.membLabl = "";
                    params.refDpId = sbx_dataPoint.getValue();
                    params.condBasDpId = "";

                    if (dlt_enum.getRowCount() > 0) {
                        const json = dlt_com.getAllJSON();                        
                        // 참조값 체크
                        for (let i=0; i < dlt_enum.getRowCount(); i++) {
                            let data_ = {};

                            // 참조명 체크 
                            if ($c.util.isEmpty(dlt_enum.getCellData(i, "member"))) {
                                $c.win.alert("참조값 \"" + dlt_enum.getCellData(i, "enumKorLabl") + "\"에 Member를 선택 해주세요", function () { grd_enum.setFocusedCell(i, 1, true); });
                                return;
                            }

                            // Member명 조회
                            const obj = json.find(function(item){
                                            return item.elmtId ===  dlt_enum.getCellData(i, "member");
                                        });

                            data_.enumVal = dlt_enum.getCellData(i, "enumVal");
                            data_.enumKorLabl = dlt_enum.getCellData(i, "enumKorLabl");
                            data_.enumEnLabl = dlt_enum.getCellData(i, "enumEnLabl");
                            data_.mappAxisId = dlt_list.getCellData(scwin.selIndex, "elmtId");
                            data_.membId = dlt_enum.getCellData(i, "member");                           
                            data_.membLabl = obj.elmtKorLabl;
                            data_.membOrd = i + 1;
                            list.push(data_);
                        }                        
                        params.enumList = list;                                         
                    } else {
                        params.enumList = null;
                    }
                } else {
                    params.axisId = dlt_list.getCellData(scwin.selIndex, "elmtId");
                    params.axisLabl = dlt_list.getCellData(scwin.selIndex, "elmtKorLabl");
                    params.axisTypCd = dlt_list.getCellData(scwin.selIndex, "dataTp");
                    params.membId = "";
                    params.membLabl = "";
                    params.refDpId = "";
                    params.condBasDpId = "";
                    params.enumList = null;
                }
                $c.win.closePopup(params);
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // 버튼 숨김 처리
                    scwin.fnButtonVisible("0");
                    // 전체 펼치기
                    grd_list.spanAll(true);
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            scwin.fnSearch = function () {

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };

            scwin.fnButtonVisible = function (val) {

                //  체크된 항목 정보 임시 저장
                scwin.rdoVal = val;
                // 고정적으로 사용못하게 하는 객체
                sbx_dataPoint.setDisabled(true);
                grp_content2_2.hide();
                grp_content2_3.hide();
                grp_content1_3.hide();
                tbx_content2.hide();

                if (val === "0") {
                    grp_content1_1.show();
                    grp_content1_2.show();                        
                    grp_content2_1.hide();                        
                    grp_content3_1.hide();
                    grp_content3_2.hide();
                    tbx_content3.hide();
                } else if (val === "1") {
                    grp_content1_1.hide();
                    grp_content1_2.hide();                        
                    grp_content2_1.show();
                    grp_content3_1.hide();
                    grp_content3_2.hide();
                    tbx_content3.hide();
                } else {
                    grp_content1_1.hide();
                    grp_content1_2.hide();                        
                    grp_content2_1.hide();                        
                    grp_content3_1.show();
                    grp_content3_2.show();
                    tbx_content3.show();
                }

                // 그리드 번튼 숨김 처리
                for (let i=0; i < dlt_list.getRowCount(); i++) {
                    if (val === "0") {
                        if (dlt_list.getCellData(i, "elmtTp") === "MEMB" && dlt_list.getCellData(i, "isLeaf") === "1") {
                            grd_list.setCellStyle(i, "isButton", "visibility", "");
                        } else {
                            grd_list.setCellStyle(i, "isButton", "visibility", "hidden");
                        }                        
                    } else if (val === "1") {
                        if (dlt_list.getCellData(i, "elmtTp") === "EXPL_AXIS") {
                            grd_list.setCellStyle(i, "isButton", "visibility", "");
                        } else {
                            grd_list.setCellStyle(i, "isButton", "visibility", "hidden");
                        }                        
                    } else {
                        if (dlt_list.getCellData(i, "elmtTp") === "TYPD_AXIS") {
                            grd_list.setCellStyle(i, "isButton", "visibility", "");
                        } else {
                            grd_list.setCellStyle(i, "isButton", "visibility", "hidden");
                        }                       
                    }
                }                
            };

            scwin.fnButtonProc = function () {

                // 그리드 button 스타일 변경
                const options = {
                    target: "선택됨",
                    backColor: "blue",
                    color: "white",
                    resBackColor: "white",
                    resColor: "black"
                };                    
                $c.tms.setGridButton(grd_list, options);
            };
